//! `java.util.Locale.getAvailableLocales()` and
//! `java.util.TimeZone.getAvailableIDs()` of JDK 25.
//!
//! **Divergence.** The JVM computes both lists from its locale
//! providers (CLDR) and its time zone database. Rust's standard library has
//! neither, so the port embeds the lists JDK 25 reports, generated by the
//! oracle (`jdk/data/available_locales.txt`, `available_time_zones.txt`),
//! already sorted as `RandomizedTest.randomLocale` and `randomTimeZone` sort
//! them. A [`Locale`] carries only its `toString()` and `toLanguageTag()`, a
//! [`TimeZone`] only its ID: the rules behind them are not available.

use std::fmt;
use std::sync::LazyLock;

/// A `java.util.Locale` of JDK 25's available locales.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Locale {
    display: &'static str,
    language_tag: &'static str,
}

impl Locale {
    /// `Locale.toLanguageTag()`.
    pub fn to_language_tag(&self) -> &'static str {
        self.language_tag
    }
}

impl fmt::Display for Locale {
    /// `Locale.toString()`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.display)
    }
}

/// A `java.util.TimeZone` of JDK 25's available IDs.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct TimeZone {
    id: &'static str,
}

impl TimeZone {
    /// `TimeZone.getID()`.
    pub fn id(&self) -> &'static str {
        self.id
    }
}

static LOCALES: LazyLock<Vec<Locale>> = LazyLock::new(|| {
    include_str!("data/available_locales.txt")
        .lines()
        .filter(|l| !l.is_empty())
        .map(|l| {
            let (display, language_tag) = l.split_once('\t').expect("locale\ttag");
            Locale {
                display,
                language_tag,
            }
        })
        .collect()
});

static TIME_ZONES: LazyLock<Vec<TimeZone>> = LazyLock::new(|| {
    include_str!("data/available_time_zones.txt")
        .lines()
        .filter(|l| !l.is_empty())
        .map(|id| TimeZone { id })
        .collect()
});

/// `Locale.getAvailableLocales()` sorted by `Locale.toString()`.
pub fn available_locales_sorted() -> &'static [Locale] {
    &LOCALES
}

/// `TimeZone.getAvailableIDs()` sorted.
pub fn available_time_zones_sorted() -> &'static [TimeZone] {
    &TIME_ZONES
}
